import requests
u='https://eutils.ncbi.nlm.nih.gov/entrez/eutils/esearch.fcgi'
params={'db':'pubmed','term':'(patient-specific quality assurance OR PSQA) AND (IMRT OR VMAT) AND (gamma passing rate OR delivery errors OR clinical significance)','retmax':12,'retmode':'json','sort':'relevance'}
r=requests.get(u,params=params,timeout=20); print('status',r.status_code); ids=r.json()['esearchresult']['idlist']; print(ids)
if ids:
 s=requests.get('https://eutils.ncbi.nlm.nih.gov/entrez/eutils/esummary.fcgi',params={'db':'pubmed','id':','.join(ids),'retmode':'json'},timeout=20).json()['result']
 for i in ids:
  x=s[i]; print(i, x.get('pubdate'), x.get('title'))
 f=requests.get('https://eutils.ncbi.nlm.nih.gov/entrez/eutils/efetch.fcgi',params={'db':'pubmed','id':','.join(ids),'rettype':'abstract','retmode':'text'},timeout=20); print(f.text[:12000])
